// [RASTREIO 5] Webhook status_lead do Kommo (chaves planas: body['leads[status][0][id]']).
// Só segue o que está no mapa de etapas: o resto nem chega a gastar chamada no Kommo.
const cfg = $('configuracoes').first().json;
const mapa = new Set((cfg.etapas_mapeadas || []).map(String));
const out = [];
for (const it of $('gatilho').all()) {  // o gatilho, nao o $input: antes daqui roda o configuracoes
  const b = it.json.body || {};
  if (cfg.kommo_conta && String(b['account[id]']) !== String(cfg.kommo_conta)) continue;  // post forjado
  for (let i = 0; i < 50; i++) {
    const k = (campo) => b[`leads[status][${i}][${campo}]`];
    if (k('id') === undefined) break;
    const chave = `${k('pipeline_id')}:${k('status_id')}`;
    if (!mapa.has(chave)) continue;
    out.push({ json: {
      lead_id: Number(k('id')), pipeline_id: Number(k('pipeline_id')), status_id: Number(k('status_id')),
      status_anterior: Number(k('old_status_id')) || null, valor_webhook: k('price') ?? null,
      ocorrido_em: new Date((Number(k('last_modified')) || Math.floor(Date.now() / 1000)) * 1000).toISOString(),
      lead_url: `${cfg.kommo_api}/leads/${k('id')}?with=contacts`,
    } });
  }
}
return out;

// [RASTREIO 5] Lido o lead: guarda valor e rastreio do Kommo e monta o endereço do contato principal.
function corpo(j) {
  if (j.error) {
    const m = String((j.error && j.error.message) || j.error);
    if (/401|403|unauthori|forbidden|credential/i.test(m)) throw new Error('Kommo recusou a credencial: ' + m.slice(0, 200));
    return null;
  }
  const st = Number(j.statusCode || 200);
  if (st === 401 || st === 403) throw new Error('Kommo recusou a credencial (HTTP ' + st + ')');
  if (st >= 400 || st === 204) return null;
  let b = j.body !== undefined ? j.body : j.data;
  if (typeof b === 'string') { if (!b.trim()) return null; b = JSON.parse(b); }
  return b || null;
}
const cfg = $('configuracoes').first().json;
const fontes = $('extrai').all();
const respostas = $input.all();
if (fontes.length !== respostas.length) throw new Error(`pareamento quebrado: ${fontes.length} x ${respostas.length}`);
const t = cfg.campos_tracking || {};
const out = [];
respostas.forEach((it, i) => {
  const r = fontes[i].json;
  const lead = corpo(it.json);
  if (!lead || !lead.id) return;  // lead apagado entre o webhook e a leitura: nada a enviar
  const cf = {};
  for (const f of (lead.custom_fields_values || [])) cf[f.field_id] = ((f.values || [])[0] || {}).value;
  const contatos = ((lead._embedded || {}).contacts) || [];
  const principal = contatos.find((c) => c.is_main) || contatos[0] || null;
  out.push({ json: { ...r,
    valor: lead.price ?? r.valor_webhook ?? null,
    gclid: t.GCLID ? (cf[t.GCLID] || null) : null,
    fbclid: t.FBCLID ? (cf[t.FBCLID] || null) : null,
    // sem contato, relê o próprio lead: o monta acha zero telefone e o banco decide pelo clique
    contato_url: principal ? `${cfg.kommo_api}/contacts/${principal.id}` : `${cfg.kommo_api}/leads/${lead.id}`,
  } });
});
return out;

// [RASTREIO 5] Telefones e e-mails do contato vão CRUS para o banco; o hash é feito lá (rastreio_etapa).
function corpo(j) {
  if (j.error) {
    const m = String((j.error && j.error.message) || j.error);
    if (/401|403|unauthori|forbidden|credential/i.test(m)) throw new Error('Kommo recusou a credencial: ' + m.slice(0, 200));
    return null;
  }
  const st = Number(j.statusCode || 200);
  if (st === 401 || st === 403) throw new Error('Kommo recusou a credencial (HTTP ' + st + ')');
  if (st >= 400 || st === 204) return null;
  let b = j.body !== undefined ? j.body : j.data;
  if (typeof b === 'string') { if (!b.trim()) return null; b = JSON.parse(b); }
  return b || null;
}
const fontes = $('contato').all();
const respostas = $input.all();
if (fontes.length !== respostas.length) throw new Error(`pareamento quebrado: ${fontes.length} x ${respostas.length}`);
const out = [];
respostas.forEach((it, i) => {
  const r = fontes[i].json;
  const c = corpo(it.json) || {};
  const valores = (code) => (c.custom_fields_values || []).filter((f) => f.field_code === code)
    .flatMap((f) => (f.values || []).map((v) => String(v.value || '').trim())).filter(Boolean);
  out.push({ json: { p: {
    lead_id: r.lead_id, pipeline_id: r.pipeline_id, status_id: r.status_id, ocorrido_em: r.ocorrido_em,
    valor: r.valor, gclid: r.gclid, fbclid: r.fbclid,
    telefones: valores('PHONE').slice(0, 5), emails: valores('EMAIL').slice(0, 5),
  } } });
});
return out;
